-- Give a permission
GRANT SELECT ON dbo.Employee TO ReportingUser;

-- Explicitly block a permission
DENY DELETE ON dbo.Employee TO ReportingUser;

-- Remove a previous GRANT or DENY
REVOKE SELECT ON dbo.Employee FROM ReportingUser;

GRANT SELECT ON dbo.Employee TO db_datareader;
DENY SELECT ON dbo.Employee TO ReportingUser;

-- ReportingUser is a member of db_datareader (has SELECT)
-- ReportingUser STILL cannot SELECT — DENY overrides every GRANT
